import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;

  // Root group
  const root = new Group();

  // ---------- Backdrop ----------
  const bgGeom = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial({
    color: mix(color('#1a1a22'), color('#121218'), uv().y),
  });
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  // ---------- Text items ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const [kickerItem, ...brandItems] = items;

  // Kicker
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(kickerItem.text ?? kickerItem, {
      fontSize: kickerItem.typography?.fontSize ?? 9,
      color: '#e8ecf2',
    });
    kicker.position.set(0, 1.05, 0.01);
    root.add(kicker);
  }

  // ---------- Tile grid ----------
  const tileWidth = 1.0;
  const tileHeight = 0.62;
  const gap = 0.25;
  const depth = 0.02;

  const cols = 3;
  const rows = 2;
  const totalWidth = cols * tileWidth + (cols - 1) * gap; // 3.5
  const totalHeight = rows * tileHeight + (rows - 1) * gap; // 1.49

  const startX = -totalWidth / 2 + tileWidth / 2; // -1.25
  const startY = totalHeight / 2 - tileHeight / 2; // 0.435

  const tiles = [];

  // Base tile material (node based gradient)
  const baseTileMat = new MeshStandardNodeMaterial({
    color: mix(color('#1a1a22'), color('#121218'), uv().y),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.0,
  });
  // anisotropy is a standard material property
  baseTileMat.anisotropy = 0.6; // strength
  // orientation for anisotropy (aligned to X)
  baseTileMat.anisotropyDirection = new ctx.THREE.Vector3(1, 0, 0);

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const idx = row * cols + col;

      const geom = new BoxGeometry(tileWidth, tileHeight, depth);
      const mat = baseTileMat.clone();
      mat.transparent = true;
      mat.opacity = 0; // start invisible for stagger animation

      const tile = new Mesh(geom, mat);
      tile.position.set(
        startX + col * (tileWidth + gap),
        startY - row * (tileHeight + gap),
        0
      );
      root.add(tile);
      tiles.push(tile);

      // Brand text on tile
      const brandItem = brandItems[idx];
      if (brandItem) {
        const txt = ctx.fontAtlas.createText(brandItem.text ?? brandItem, {
          fontSize: brandItem.typography?.fontSize ?? 13,
          color: '#e8ecf2',
        });
        // center text on tile surface
        txt.position.set(0, 0, depth / 2 + 0.001);
        // initial opacity 0.78
        if (txt.material) {
          txt.material.transparent = true;
          txt.material.opacity = 0.78;
        }
        tile.add(txt);

        // Hover animations (enter / leave)
        const hoverEnter = () => {
          const tl = gsap.timeline();
          tl.to(
            tile.position,
            { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
            0
          );
          tl.to(
            txt.material,
            { opacity: 1.0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
            0
          );
          tile.userData._hoverTl = tl;
        };
        const hoverLeave = () => {
          const tl = gsap.timeline();
          tl.to(
            tile.position,
            { z: 0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
            0
          );
          tl.to(
            txt.material,
            { opacity: 0.78, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
            0
          );
          tile.userData._hoverTl = tl;
        };
        // expose per‑tile handlers via root userData
        if (!root.userData.handlers) root.userData.handlers = {};
        root.userData.handlers[`hoverEnter_${idx}`] = hoverEnter;
        root.userData.handlers[`hoverLeave_${idx}`] = hoverLeave;
      }
    }
  }

  // ---------- Staggered mount animation ----------
  const mountTl = gsap.timeline();
  tiles.forEach((tile, i) => {
    mountTl.from(
      tile.position,
      {
        y: tile.position.y + 0.2,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      i * 0.08
    );
    mountTl.from(
      tile.material,
      {
        opacity: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      i * 0.08
    );
  });

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // stop any GSAP timelines
    gsap.globalTimeline.clear();
    if (mountTl) mountTl.kill();

    // dispose tiles
    tiles.forEach((tile) => {
      if (tile.geometry) tile.geometry.dispose();
      if (tile.material) tile.material.dispose();
      if (tile.userData && tile.userData._hoverTl) tile.userData._hoverTl.kill();
    });

    // dispose background
    if (bgGeom) bgGeom.dispose();
    if (bgMat) bgMat.dispose();
  };

  return root;
}
